        assertThat(matchedInstanceId).isNotNull();
        assertThat(wrongColorInstanceId).isNotNull();
        assertThat(wrongTagNameInstanceId).isNotNull();

        String supportCardId = "TSUP_SEARCH_COMPOSITE_" + System.nanoTime();
