    @Test
    void attackArtShouldApplyOfficialPassiveGiftHbp05065DamageReductionFortyWhenDiceOdd() {
        Mockito.when(diceService.rollD6()).thenReturn(1);

        StartedMatchContext context = createStartedMatch("gift-hbp05065-odd-host", "gift-hbp05065-odd-guest");
        Long matchId = context.matchId();
        Long hostId = context.hostId();
        Long guestId = context.guestId();

        Long giftHolderCardInstanceId = createStageHolomemWithSingleCard(
            matchId,
            guestId,
            "HBP05-065",
            "COLLAB",
            "FIRST",
            0
        );
        Long giftHolderHolomemId = loadHolomemIdByCardInstanceId(matchId, guestId, giftHolderCardInstanceId);

        String durableTargetCardId = createMemberCardDefinition("THBP05065_ODD_TGT", "HBP05-065 奇數減傷目標", "DEBUT", 300, "YELLOW");
        Long guestCenterCardInstanceId = loadFirstCenterCardInstanceId(matchId, guestId);
        jdbcTemplate.update(
            """
            UPDATE match_cards
            SET card_id = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE match_id = ?
              AND owner_user_id = ?
              AND id = ?
            """,
            durableTargetCardId,
            matchId,
            guestId,
            guestCenterCardInstanceId
        );
        jdbcTemplate.update(
            """
            UPDATE match_holomems
            SET card_id = ?,
                current_level = 'DEBUT',
                damage_taken = 0,
                updated_at = CURRENT_TIMESTAMP
            WHERE match_id = ?
              AND owner_user_id = ?
              AND match_card_id = ?
            """,
            durableTargetCardId,
            matchId,
            guestId,
            guestCenterCardInstanceId
        );
        Long guestCenterHolomemId = loadHolomemIdByCardInstanceId(matchId, guestId, guestCenterCardInstanceId);

        Long attackerCardInstanceId = createStageHolomemWithArtAndCheer(
            matchId,
            hostId,
            "COLLAB",
            180,
            "RED",
            100,
            "{}",
            "{\"type\":\"DAMAGE\",\"target\":\"ANY_HOLOMEM\",\"value\":100,\"rawHeader\":\"測試藝能 100\"}",
            0,
            "RED",
            "T5065OD"
        );

        jdbcTemplate.update(
            """
            UPDATE matches
            SET turn_number = 2,
                current_turn_player_id = ?,
                current_phase = 'MAIN',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            hostId,
            matchId
        );
        entityManager.clear();
        advanceToPerformancePhase(matchId, hostId, attackerCardInstanceId);

        Integer maxActionOrderBeforeAttack = jdbcTemplate.queryForObject(
            """
            SELECT COALESCE(MAX(action_order), 0)
            FROM match_actions
            WHERE match_id = ?
              AND turn_number = 2
            """,
            Integer.class,
            matchId
        );

        AttackArtActionRequest attack = new AttackArtActionRequest();
        attack.setAttackerCardInstanceId(attackerCardInstanceId);
        attack.setTargetCardInstanceId(guestCenterCardInstanceId);
        matchActionService.attackArt(matchId, hostId, attack);

        String payloadText = jdbcTemplate.queryForObject(
            """
            SELECT payload::text
            FROM match_actions
            WHERE match_id = ?
              AND user_id = ?
              AND action_type = 'ATTACK_ART'
            ORDER BY id DESC
            LIMIT 1
            """,
            String.class,
            matchId,
            hostId
        );
        Integer damageTaken = jdbcTemplate.queryForObject(
            "SELECT damage_taken FROM match_holomems WHERE id = ?",
            Integer.class,
            guestCenterHolomemId
        );

        assertThat(payloadText).containsPattern("\"passiveGiftIncomingDamageReduction\"\\s*:\\s*40");
        assertThat(payloadText).containsPattern("\"incomingDamageReduction\"\\s*:\\s*40");
        assertThat(payloadText).containsPattern("\"artTotalDamage\"\\s*:\\s*60");
        assertThat(damageTaken).isEqualTo(60);

        String giftTriggerPayloadText = jdbcTemplate.query(
            """
            SELECT payload::text
            FROM match_actions
            WHERE match_id = ?
              AND user_id = ?
              AND action_type = 'GIFT_TRIGGER'
              AND payload ->> 'triggerType' = 'PASSIVE_INCOMING_DAMAGE_REDUCTION'
            ORDER BY id DESC
            LIMIT 1
            """,
            rs -> rs.next() ? rs.getString("payload") : "",
            matchId,
            guestId
        );
        assertThat(giftTriggerPayloadText).containsPattern("\"triggerType\"\\s*:\\s*\"PASSIVE_INCOMING_DAMAGE_REDUCTION\"");
        assertThat(giftTriggerPayloadText).containsPattern("\"giftHolderHolomemId\"\\s*:\\s*" + giftHolderHolomemId);
        assertThat(giftTriggerPayloadText).containsPattern("\"giftText\"\\s*:");
        assertThat(giftTriggerPayloadText).contains("サイコロを1回振れる");
        assertThat(giftTriggerPayloadText).containsPattern("\"diceRoll\"\\s*:\\s*1");

        Integer giftTriggerActionOrder = jdbcTemplate.queryForObject(
            """
            SELECT action_order
            FROM match_actions
            WHERE match_id = ?
              AND user_id = ?
              AND action_type = 'GIFT_TRIGGER'
              AND payload ->> 'triggerType' = 'PASSIVE_INCOMING_DAMAGE_REDUCTION'
            ORDER BY id DESC
            LIMIT 1
            """,
            Integer.class,
            matchId,
            guestId
        );
        Integer attackArtActionOrder = jdbcTemplate.queryForObject(
            """
            SELECT action_order
            FROM match_actions
            WHERE match_id = ?
              AND user_id = ?
              AND action_type = 'ATTACK_ART'
            ORDER BY id DESC
            LIMIT 1
            """,
            Integer.class,
            matchId,
            hostId
        );
        assertThat(giftTriggerActionOrder).isGreaterThan(maxActionOrderBeforeAttack);
        assertThat(giftTriggerActionOrder).isLessThan(attackArtActionOrder);
    }

