        Long greenCheerA = attachTrackedTestCheer(matchId, guestId, targetHolomemId, "GREEN", "hbp01004-green-a");
        Long greenCheerB = attachTrackedTestCheer(matchId, guestId, targetHolomemId, "GREEN", "hbp01004-green-b");
